Future<void>main()async{WidgetsFlutterBinding.ensureInitialized();tz.initializeTimeZones();tz.setLocalLocation(tz.getLocation('Asia/Tehran'));await npl.initialize(const InitializationSettings(android:AndroidInitializationSettings('@mipmap/ic_launcher')));await npl.resolvePlatformSpecificImplementation<AndroidFlutterLocalNotificationsPlugin>()?.requestNotificationsPermission();runApp(const App());}
