class AppState extends State<App>{String font='Vazirmatn';bool dark=false;@override void initState(){super.initState();load();}Future<void>load()async{final p=await SharedPreferences.getInstance();setState((){font=p.getString('font')??'Vazirmatn';dark=p.getBool('dark')??false;});}Future<void>fontSet(String x)async{final p=await SharedPreferences.getInstance();await p.setString('font',x);setState(()=>font=x);}Future<void>darkSet(bool x)async{final p=await SharedPreferences.getInstance();await p.setBool('dark',x);setState(()=>dark=x);}@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,title:'آروین',theme:ThemeData(useMaterial3:true,fontFamily:font),darkTheme:ThemeData(useMaterial3:true,fontFamily:font,brightness:Brightness.dark),themeMode:dark?ThemeMode.dark:ThemeMode.light,home:Directionality(textDirection:TextDirection.rtl,child:Home(font:font,dark:dark,onFont:fontSet,onDark:darkSet)));}
